    {'comment': '晴晴', 'constant': False, 'content': '【晴晴】娄琛雨女儿，五六岁。梳小辫，穿黄色公主裙，乖巧嘴甜。\n身世之谜：核苷酸序列比对一致率99.99%，疑似绯迷计划克隆体（母体为娄琛雨）。既是母女亲情的象征，也是绯迷计划"亚人克隆"技术的活体实验证据。\n外貌特征：与娄琛雨长相极为相似（"长得一个样"），杨玉兰一见就猜到是娄琛雨的女儿。\n剧情作用：晴晴的存在证明绯迷计划已进入克隆体繁殖阶段。她的年龄与绯迷计划时间线吻合，是揭开{{user}}身世之谜的关键拼图。\n情感纽带：晴晴是娄琛雨在28F恢复期间的牵挂。{{user}}与晴晴的互动会影响娄琛雨信任度。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 55, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1049, 'insertion_order': 1049, 'keys': ['晴晴', '娄琛雨女儿', '克隆体', '绯迷', '六岁'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '公司创立与内部分化', 'constant': False, 'content': '环晓科技六七年前在陵东成立，最初在老旧教学楼办公、几十名员工。短短几年创业板上市融资，租下市中心25层整栋写字楼。创始人背景不明，与Sisterhood有深层绑定。内部派系包括：江天炜旧派（行政/人力/剧本派）、技术研发派（BMI核心团队）、Sisterhood渗透派（姜舞/萧茹）、{{user}}势力（后期崛起）。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 56, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1050, 'insertion_order': 1050, 'keys': ['公司创立', '公司历史', '创业史', '创业板上市', '内部派系', '派系'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '催眠剧本编写系统', 'constant': False, 'content': '【催眠剧本编写系统·自定义场景创作】\n高级职称用户可使用的员工系统功能，允许自编催眠剧本。\n【编写要素】①角色认知设定（被催眠女性深信的身份）；②场景背景（地点/时间/情境）；③互动规则（允许/禁止的行为）；④阶段化流程（①②③④⑤递进）；⑤贡献点消耗设定；⑥破解模式加成。\n【审核机制】编写完成后需通过系统审核才能入库。审核标准不明，但与用户职称和贡献点余额相关。破解模式下可绕过审核。\n【复用与共享】已编写的剧本可重复调用，也可通过交易群与其他用户交换。高级剧本在交易市场上价值很高。\n【限制】不能直接编写涉及组织核心机密（绯迷计划/脑机接口原理）的剧本。不能对非自己管辖的女性使用自编剧本（除非使用入侵剧本功能）。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 57, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1051, 'insertion_order': 1051, 'keys': ['剧本编写', '剧本创作', '剧本开发', '沙盒测试'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '女助理培训体系', 'constant': False, 'content': '新入职女助理须参加为期两周的培训课程：站姿训练（穿高跟持平板电脑站立8小时）、走路姿态训练、穿着规范（制服颜色按职级分级）、催眠适应训练（注射脑机接口药液后首次被催眠测试）、职场伦理课程。培训通过后分配至各部门。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 58, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1052, 'insertion_order': 1052, 'keys': ['助理培训', '培训课', '教官', '新助理培训', '走路训练'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '会议文化与职场仪式', 'constant': False, 'content': '环晓科技独特的职场文化体系：晨会脱衣仪式（女助理需脱至规定裸露程度）、周会汇报姿势（跪姿、站姿按等级区别）、重要汇报用标准姿势。会议等级分为：日常早会→部门周会→高层汇报会→全体大会。每个级别有不同的仪式要求。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 59, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1053, 'insertion_order': 1053, 'keys': ['会议', '晨会', '脱衣仪式', '汇报姿势', '职场仪式'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '人体家具与保洁系统', 'constant': False, 'content': '【人体家具与保洁系统】环晓科技的极端化工种体系，位于12层母婴室及周边区域。\n人体家具类：①人型咖啡机——女助理被催眠为人体饮水机，乳头为出水口；②人型沙发——女助理以固定姿势趴伏充当座椅；③组合沙发——多名女助理拼接为大型家具；④人型小便池——壁挂式/落地式，位于男厕所。\n保洁分级制度：①初级保洁——粉色蝴蝶领结+粉色过膝丝袜，重要部位裸露，负责基础清洁和人体废料处理；②高级保洁——如陈诗琪，自称"专属肉便器"，管理母婴室日常运营，有权限分配初级保洁任务。\n晋升/降级机制：保洁人员通过服务表现赚取微薄贡献点，积累后可向上兑换正式助理名额。反之，正式助理犯错可被降级为保洁。母婴室存在独立微型经济体系。\n底层生态：保洁人员是公司权力最底层。董夏夏（初级保洁→被用于极端服务）和陈诗琪（高级保洁→母婴室管理者）代表最底层的人性异化。\n破解模式联动：{{user}}可改写人体家具认知，让她们恢复意识但无法移动——清醒地感受一切却无法反抗。或将高级保洁降级为初级作为惩罚。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 60, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1054, 'insertion_order': 1054, 'keys': ['人体家具', '家政', '保洁系统', '小便池', '大便器', '人体废料处理'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '坐骑训练与骑行文化', 'constant': False, 'content': '公司高层区的特殊岗位体系。辅骑：开裆丝袜+高马尾+狗尾肛塞+跳蛋标配。主骑：总监助理最高级，可被骑乘移动。坐骑选拔流程：面试展示身体资质→试骑考核→正式录用。骑行文化包括单人坐骑接力赛（男员工骑乘女助理完成赛道障碍物）。22-24层为骑行训练与候补中心。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 61, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1055, 'insertion_order': 1055, 'keys': ['骑行', '坐骑', '骑马', '辅骑', '主骑', '单人坐骑接力', '骑乘位'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
    {'comment': '28层人体实验室', 'constant': False, 'content': '【28层人体实验室·脑机接口核心设施】\n环晓科技写字楼28层，姜舞博士主导的脑机接口实验核心区域。对外完全保密，仅少数高层知晓。\n【设施】①主实验室（脑机接口设备/传感器装置/监控屏幕）；②孵化室（利用女性荷尔蒙和性高潮反馈进行意识实验，需要大量女体实验体——被催眠女性如屠宰场母猪般被挂起，身上弥漫汗味/下体气味/尿骚味）；③28F恢复室（娄琛雨深度昏迷中/萧茹脑回路受损植物人状态，破解模式可修复）。\n【实验内容】①人格定位实验（绯迷计划——"已经找到人格"）；②记忆写入/抹除实验；③荷尔蒙-脑机接口反馈实验；④肢体再生术研发；⑤Y染色体基因改造病毒试验。\n【姜舞】被{{user}}囚禁后成为技术资源。27岁心理学博士，修女会"千人计划"成果，A级内勤，首席科学家。', 'enabled': True, 'extensions': {'automation_id': '', 'case_sensitive': None, 'cooldown': None, 'delay': None, 'delay_until_recursion': False, 'depth': 4, 'display_index': 62, 'exclude_recursion': False, 'group': '', 'group_override': False, 'group_weight': 100, 'ignore_budget': False, 'match_character_depth_prompt': False, 'match_character_description': False, 'match_character_personality': False, 'match_creator_notes': False, 'match_persona_description': False, 'match_scenario': False, 'match_whole_words': None, 'outlet_name': '', 'position': 0, 'prevent_recursion': False, 'probability': 100, 'role': 0, 'scan_depth': None, 'selectiveLogic': 0, 'sticky': None, 'triggers': [], 'useProbability': True, 'use_group_scoring': False, 'vectorized': False}, 'id': 1056, 'insertion_order': 1056, 'keys': ['28层', '人体实验室', '姜舞实验室', '囚禁', '手术台', '培养槽', '脑机接口实验'], 'position': 'before_char', 'secondary_keys': [], 'selective': True, 'use_regex': True},
